def frequency_windows(text):
    v = list(map(int, text.split()))
    (n, w, k) = v[:3]
    a = v[3:]
    counts = Counter()
    eligible = []
    out = []
    for (i, x) in enumerate(a):
        counts[x] += 1
        if counts[x] == k:
            heapq.heappush(eligible, x)
        if i >= w:
            counts[a[i - w]] -= 1
        if i >= w - 1:
            while eligible and counts[eligible[0]] < k:
                heapq.heappop(eligible)
            out.append(eligible[0] if eligible else -1)
    return ' '.join(map(str, out))
import sys
sys.stdout.write(frequency_windows(sys.stdin.read()) + '\n')

import ast, math, itertools, random, heapq, bisect
from collections import Counter, deque

def array(text):
    s = text.strip()
    if not s:
        return []
    try:
        value = ast.literal_eval(s)
        if isinstance(value, (list, tuple)):
            return list(value)
        if isinstance(value, int):
            return [value]
    except (ValueError, SyntaxError):
        pass
    return list(map(int, s.split()))

def reach(text):
    a = array(text)
    far = 0
    for (i, x) in enumerate(a):
        if i > far:
            return 'false'
        far = max(far, i + x)
    return 'true'
import sys
